// Generate 3-3-3 pattern meeting code (e.g. abc-def-ghi)
const generateMeetingCode = () => {
  const chars = "abcdefghjkmnpqrstuvwxyz23456789";
  let code = "";
  const randomBytes = crypto.randomBytes(9);
  for (let i = 0; i < 9; i++) {
    code += chars[randomBytes[i] % chars.length];
    if (i === 2 || i === 5) {
      code += "-";
    }
  }
  return code;
};

