const LoadingScreen: React.FC<{ message?: string }> = ({ message = 'Loading...' }) => (
  <div className="onboarding-page">
    <div className="auth-ambient" />
    <div className="onboarding-container">
      <h1>{message}</h1>
      <p className="onboarding-desc">Hang tight, we’re getting things ready.</p>
    </div>
  </div>
);

const ProtectedRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated, isReady } = useAuth();
  if (!isReady) return <LoadingScreen message="Preparing your workspace..." />;
  if (!isAuthenticated) return <Navigate to="/login" replace />;
  return <>{children}</>;
};

const PublicRoute: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isAuthenticated, isReady } = useAuth();
  if (!isReady) return <LoadingScreen message="Preparing your session..." />;
  if (isAuthenticated) return <Navigate to="/" replace />;
  return <>{children}</>;
};

const AppRoutes: React.FC = () => {
  return (
    <Routes>
      <Route path="/login" element={<PublicRoute><LoginPage /></PublicRoute>} />
      <Route path="/register" element={<PublicRoute><RegisterPage /></PublicRoute>} />
      <Route
        path="/meet/:meetingCode"
        element={
          <ProtectedRoute>
            <MeetingProvider>
              <MeetingPage />
            </MeetingProvider>
          </ProtectedRoute>
        }
      />
      <Route
        path="/*"
        element={
          <ProtectedRoute>
            <WorkspaceProvider>
              <UnreadProvider>
                <CallProvider>

element={
          <ProtectedRoute>
            <MeetingProvider>
              <MeetingPage />
            </MeetingProvider>
          </ProtectedRoute>
        }
      />
      <Route
        path="/*"
        element={
          <ProtectedRoute>
            <WorkspaceProvider>
              <UnreadProvider>
                <CallProvider>
                  <MeetingProvider>
                    <DashboardPage />
                    <IncomingCallModal />
                    <ActiveCallModal />
                  </MeetingProvider>
                </CallProvider>
              </UnreadProvider>
            </WorkspaceProvider>
          </ProtectedRoute>
        }
      />
    </Routes>
  );
};

const App: React.FC = () => {
  return (
    <BrowserRouter>
      <AuthProvider>
        <AppRoutes />
      </AuthProvider>
    </BrowserRouter>
  );
};

export default App;

