    const emoji = customInput.trim();
    if (emoji && isValidReactionEmoji(emoji)) {

setOpenDown(anchorRect.top - containerRect.top < 170);
        }
      }
      return next;
    });
  };

  const handleToggle = (emoji: string) => {
    setPickerOpen(false);
    onToggle(emoji);
  };

  const submitCustom = () => {
    const emoji = customInput.trim();
    if (emoji && isValidReactionEmoji(emoji)) {
      handleToggle(emoji);
      setCustomInput('');
    }
  };

  return (
    <div className="reaction-bar">
      {reactions.map((reaction) => {
