        rejectCall('declined');
        return;
      }

      setLocalStream(stream);
      localStreamRef.current = stream;
      isAcquiringMediaRef.current = false;

      const pc = createPeerConnection(incomingCall.caller.user_id);
      stream.getTracks().forEach((track) => {
        pc.addTrack(track, stream);
      });

