  const rejectCall = (reason: 'declined' | 'busy' = 'declined') => {
    stopAllTones();
    if (incomingCall) {
      emitCallReject({ call_id: incomingCall.call_id, reason });
    }
    cleanUpMediaAndPeer();
    setIncomingCall(null);
    setCallState('idle');
    setRemoteUser(null);
    setCallId(null);

setCallState('idle');
    }
  };

  // ── Reject Call ────────────────────────────────────────────────────────────
  const rejectCall = (reason: 'declined' | 'busy' = 'declined') => {
    stopAllTones();
    if (incomingCall) {
      emitCallReject({ call_id: incomingCall.call_id, reason });
    }
    cleanUpMediaAndPeer();
