import React, { createContext, useContext, useState, useEffect, useCallback, type ReactNode } from 'react';
import type { Workspace } from '../api/workspaces';
import { getWorkspaces } from '../api/workspaces';
import { useAuth } from './AuthContext';

interface WorkspaceContextType {
  workspaces: Workspace[];
  activeWorkspace: Workspace | null;
  setActiveWorkspace: (w: Workspace) => void;
  refreshWorkspaces: () => Promise<void>;
  loading: boolean;
}

const WorkspaceContext = createContext<WorkspaceContextType | undefined>(undefined);

export const WorkspaceProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { isAuthenticated } = useAuth();
  const [workspaces, setWorkspaces] = useState<Workspace[]>([]);
  const [activeWorkspace, setActiveWorkspace] = useState<Workspace | null>(null);
  const [loading, setLoading] = useState(false);

  const refreshWorkspaces = useCallback(async () => {
    if (!isAuthenticated) return;
    setLoading(true);
    try {
      const { data } = await getWorkspaces();
      setWorkspaces(data.workspaces);
      if (!activeWorkspace && data.workspaces.length > 0) {
        const storedWorkspaceId = localStorage.getItem('activeWorkspaceId');
        const storedWorkspace = storedWorkspaceId
          ? data.workspaces.find((ws) => ws.workspace_id === Number(storedWorkspaceId))
          : null;
        setActiveWorkspace(storedWorkspace || data.workspaces[0]);
      }
    } catch (err) {
      console.error('Failed to fetch workspaces:', err);
    } finally {
      setLoading(false);
    }
  }, [isAuthenticated, activeWorkspace]);

  useEffect(() => {
    refreshWorkspaces();
  }, [isAuthenticated]);

  const setActiveWorkspaceWithPersist = (workspace: Workspace) => {
    localStorage.setItem('activeWorkspaceId', String(workspace.workspace_id));
    setActiveWorkspace(workspace);
  };

  return (
    <WorkspaceContext.Provider value={{ workspaces, activeWorkspace, setActiveWorkspace: setActiveWorkspaceWithPersist, refreshWorkspaces, loading }}>
      {children}
    </WorkspaceContext.Provider>
  );
};

export const useWorkspace = () => {
  const ctx = useContext(WorkspaceContext);
  if (!ctx) throw new Error('useWorkspace must be used within WorkspaceProvider');

const setActiveWorkspaceWithPersist = (workspace: Workspace) => {
    localStorage.setItem('activeWorkspaceId', String(workspace.workspace_id));
    setActiveWorkspace(workspace);
  };

  return (
    <WorkspaceContext.Provider value={{ workspaces, activeWorkspace, setActiveWorkspace: setActiveWorkspaceWithPersist, refreshWorkspaces, loading }}>
      {children}
    </WorkspaceContext.Provider>
  );
};

export const useWorkspace = () => {
  const ctx = useContext(WorkspaceContext);
  if (!ctx) throw new Error('useWorkspace must be used within WorkspaceProvider');
  return ctx;
};

import { useState, useEffect, useRef, useCallback } from 'react';
import { getSocket } from '../socket/socketManager';

interface TypingUser {
  user_name: string;
  timestamp: number;
}

export const useTypingIndicator = (channelId?: number) => {
  const [typingUsers, setTypingUsers] = useState<TypingUser[]>([]);
  const timeoutRefs = useRef<Record<string, ReturnType<typeof setTimeout>>>({});

  useEffect(() => {
    if (!channelId) return;
    const socket = getSocket();

    const handleTyping = (data: { user_name: string; channel_id?: number }) => {
      if (data.channel_id !== channelId) return;
      setTypingUsers((prev) => {
        const filtered = prev.filter((u) => u.user_name !== data.user_name);
        return [...filtered, { user_name: data.user_name, timestamp: Date.now() }];
      });
      if (timeoutRefs.current[data.user_name]) {
        clearTimeout(timeoutRefs.current[data.user_name]);
      }
      timeoutRefs.current[data.user_name] = setTimeout(() => {
        setTypingUsers((prev) => prev.filter((u) => u.user_name !== data.user_name));
      }, 3000);
    };

    const handleStopTyping = (data: { user_name: string; channel_id?: number }) => {
      if (data.channel_id !== channelId) return;
      setTypingUsers((prev) => prev.filter((u) => u.user_name !== data.user_name));
    };

    socket.on('user_typing', handleTyping);
    socket.on('user_stop_typing', handleStopTyping);

    return () => {
      socket.off('user_typing', handleTyping);
      socket.off('user_stop_typing', handleStopTyping);
      Object.values(timeoutRefs.current).forEach(clearTimeout);
    };
  }, [channelId]);

  return typingUsers;
};

export const useOnlineUsers = () => {
  const [onlineUsers, setOnlineUsers] = useState<number[]>([]);

  useEffect(() => {
    const socket = getSocket();
    const handler = (users: number[]) => setOnlineUsers(users);
    socket.on('online_users', handler);
    return () => { socket.off('online_users', handler); };
  }, []);

  return onlineUsers;
};

return typingUsers;
};

export const useOnlineUsers = () => {
  const [onlineUsers, setOnlineUsers] = useState<number[]>([]);

  useEffect(() => {
    const socket = getSocket();
    const handler = (users: number[]) => setOnlineUsers(users);
    socket.on('online_users', handler);
