    };

    const onReceiveDm = (msg: any) => {
      // Do not trigger message notifications/sounds for call-history events or self-sent messages
      if (msg.message_type === 'call' || msg.call_type || (user && msg.sender_id === user.user_id)) {
        return;
      }

      try {
        const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.type = 'sine';
        osc.frequency.setValueAtTime(880, ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(440, ctx.currentTime + 0.1);
        gain.gain.setValueAtTime(0.1, ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.2);
        osc.onended = () => {
          try {
            osc.disconnect();
            gain.disconnect();
            ctx.close().catch(() => {});
          } catch {}
        };
        osc.start(ctx.currentTime);
        osc.stop(ctx.currentTime + 0.2);
      } catch (e) {
        console.log("AudioContext error", e);
      }

      setNotification({
        title: `New DM from ${msg.sender_name}`,
        message: msg.message_text.length > 40 ? msg.message_text.substring(0, 40) + '...' : msg.message_text,
      });

      setTimeout(() => setNotification(null), 5000);
    };

    socket.on('task_assigned', onTaskAssigned);
    socket.on('receive_dm', onReceiveDm);
    return () => {
